-- Read-only metadata and aggregate checks. No personal records or secrets.
select jsonb_build_object(
 'migrations',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations),
 'tables_without_rls',(select coalesce(jsonb_agg(c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity),
 'views',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'options',c.reloptions,'anon_select',has_table_privilege('anon',c.oid,'select'),'authenticated_select',has_table_privilege('authenticated',c.oid,'select'))),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='v'),
 'public_functions',(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definer',p.prosecdef,'config',p.proconfig,'anon_execute',has_function_privilege('anon',p.oid,'execute'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'execute'))),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
 'business_write_grants',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'role',r.name,'insert',has_table_privilege(r.name,c.oid,'insert'),'update',has_table_privilege(r.name,c.oid,'update'),'delete',has_table_privilege(r.name,c.oid,'delete'),'truncate',has_table_privilege(r.name,c.oid,'truncate'))),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join (values('anon'),('authenticated')) r(name) where n.nspname='public' and c.relkind='r' and (has_table_privilege(r.name,c.oid,'insert') or has_table_privilege(r.name,c.oid,'update') or has_table_privilege(r.name,c.oid,'delete') or has_table_privilege(r.name,c.oid,'truncate'))),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) from storage.buckets),
 'counts',jsonb_build_object('users',(select count(*) from auth.users),'verified_mfa_factors',(select count(*) from auth.mfa_factors where status='verified'),'memberships',(select count(*) from public.organization_members),'assignments',(select count(*) from public.work_assignments),'vendors',(select count(*) from public.procurement_vendors),'purchases',(select count(*) from public.purchase_requests),'paid_purchases',(select count(*) from public.purchase_requests where status='paid'),'journals',(select count(*) from public.accounting_journals),'clients',(select count(*) from public.sales_clients),'sales_documents',(select count(*) from public.sales_documents),'branches_without_entity',(select count(*) from public.business_units where kind='branch' and entity_id is null),'open_periods',(select count(*) from public.accounting_periods where period_status='open'))
) as audit;
